//! Declarative invariant catalog used by FormalEngine.
#[derive(Debug,Clone,Copy,PartialEq,Eq,Hash)] pub enum InvariantKind { DoubleOnion, ELayerIsolation, PermissionGrantL0, MidTaskAtomicity, SevenAdvisorVoting }
#[derive(Debug,Clone,PartialEq,Eq)] pub struct Invariant { pub kind: InvariantKind, pub name: &'static str, pub description: &'static str }
impl Invariant { pub const fn new(kind:InvariantKind,name:&'static str,description:&'static str)->Self{Self{kind,name,description}} }
pub mod presets { use super::*; pub const DOUBLE_ONION:Invariant=Invariant::new(InvariantKind::DoubleOnion,"double_onion","L0 requires human authority"); pub const E_LAYER_ISOLATION:Invariant=Invariant::new(InvariantKind::ELayerIsolation,"e_layer_isolation","cross-layer writes require permission"); pub const PERMISSION_GRANT_L0:Invariant=Invariant::new(InvariantKind::PermissionGrantL0,"permission_grant_l0","L0 requires joint authority and HA"); pub const MID_TASK_ATOMICITY:Invariant=Invariant::new(InvariantKind::MidTaskAtomicity,"mid_task_atomicity","mid-task transitions are atomic"); pub const SEVEN_ADVISOR_VOTING:Invariant=Invariant::new(InvariantKind::SevenAdvisorVoting,"7_advisor_voting","all seven advisors are present"); pub const ALL:[Invariant;5]=[DOUBLE_ONION,E_LAYER_ISOLATION,PERMISSION_GRANT_L0,MID_TASK_ATOMICITY,SEVEN_ADVISOR_VOTING]; }
